#!/bin/sh
# Generated by resources/generate-tests.py. Do not edit.
#
# Runs the quick sweep of the WebGL benchmarks: a few benchmarks of each suite, the common cases.
# 31 benchmarks.
#
#     run-quick-sweep.sh BUILD_A [BUILD_B]
#
# BUILD_A and BUILD_B are build directories that contain WebKitTestRunner, for example
# WebKitBuild/cmake-mac/Release. With BUILD_B, every benchmark runs with BUILD_A first, then with
# BUILD_B, and the tables compare them. Each suite runs with Tools/Scripts/run-webgl-benchmarks,
# which writes SUITE.csv and the WebKitTestRunner output of each benchmark to the results directory,
# $WEBGL_BENCH_RESULTS, by default /tmp/webgl-benchmarks/quick.

if [ $# -lt 1 ] || [ $# -gt 2 ]; then
    echo "Usage: $0 BUILD_A [BUILD_B]" >&2
    exit 2
fi
# A sleep of the machine during a benchmark loses the WebGL context, so keep it awake.
if [ -z "${WEBGL_BENCH_AWAKE:-}" ] && command -v caffeinate > /dev/null; then
    WEBGL_BENCH_AWAKE=1 exec caffeinate -dims "$0" "$@"
fi
build_a=$1
build_b=${2:-}
directory=$(cd "$(dirname "$0")" && pwd)
runner=$directory/../../Tools/Scripts/run-webgl-benchmarks
results=${WEBGL_BENCH_RESULTS:-/tmp/webgl-benchmarks/quick}
mkdir -p "$results"
status=0

# run_suite SUITE [BENCHMARK...]: runs the benchmarks of SUITE, or all of them if none are given.
run_suite() {
    suite=$1
    shift
    if [ $# -gt 0 ]; then
        set -- --only "$@"
    fi
    echo "== $suite" >&2
    if ! "$runner" "$build_a" ${build_b:+"$build_b"} --tests-directory "$directory/$suite" --results-directory "$results/$suite" "$@" > "$results/$suite.csv"; then
        echo "run-webgl-benchmarks failed for $suite" >&2
        status=1
    fi
}

run_suite ContextCreate \
    none \
    alpha-msaa-stencil-depth-preserve
run_suite RenderbufferClear \
    rgba8 \
    rgba8-depth24_stencil8-msaa \
    depth24_stencil8
run_suite FramebufferDraw \
    rb-rgba8 \
    tex-rgba8 \
    rb-rgba8-depth24_stencil8-msaa
run_suite HiddenSurfaceRemoval \
    lod \
    texture \
    texture-msaa
run_suite FramebufferInvalidate \
    canvas-draw \
    canvas-draw-invalidate-unwritten-texture \
    canvas-draw-depth-prepass-invalidate-unwritten-texture
run_suite TextureClear \
    rgba8 \
    depth24_stencil8
run_suite TextureInit \
    new-2d-draw \
    new-2d-sample \
    invalidate-2d-draw \
    invalidate-2d-array-draw
run_suite TextureAtlasUpload \
    rgba8-16x16 \
    rgba8-16x16-used
run_suite TextureUpload \
    rgba8-unsigned_byte-64x64 \
    rgba8-unsigned_byte-2048x2048 \
    rgba8-unsigned_byte-64x64-used
run_suite TextureSubUpload \
    rgba8-unsigned_byte-64x64 \
    rgba8-unsigned_byte-2048x2048 \
    rgba8-unsigned_byte-64x64-used
run_suite TextureStorageUpload \
    rgba8-unsigned_byte-64x64 \
    rgba8-unsigned_byte-2048x2048 \
    rgba8-unsigned_byte-64x64-pass
exit $status
